package cloud.gitwide.ampverse;

import android.app.*;
import android.content.*;
import android.widget.*;
import androidx.media3.common.MediaItem;
import java.util.*;
import org.json.*;

final class PhoneLibraryPanel extends LinearLayout {
    interface Host {void play(List<MediaItem> items);}
    private final Activity activity;private final Appearance colors;private final Host host;
    PhoneLibraryPanel(Activity a,Appearance c,Host h){super(a);activity=a;colors=c;host=h;setOrientation(VERTICAL);draw();}
    private TextView label(String text){TextView v=new TextView(activity);v.setText(text);v.setTextColor(colors.text);v.setTextSize(16);v.setPadding(8,12,8,12);return v;}
    private Button action(String text,Runnable run){Button b=new Button(activity);b.setText(text);b.setAllCaps(false);b.setTextColor(colors.classic?android.graphics.Color.BLACK:colors.text);b.setBackground(Chrome.button(colors,false));b.setOnClickListener(v->{try{run.run();}catch(Exception error){error(error);}});return b;}
    private void error(Exception error){Toast.makeText(activity,error.getMessage(),Toast.LENGTH_LONG).show();}
    private void draw(){removeAllViews();addView(label("Playlists & Smart Playlists"));addView(action("+ New playlist",()->create(false)));addView(action("+ New Smart Playlist",()->create(true)));try{JSONArray lists=PhonePlaylists.read(activity);for(int i=0;i<lists.length();i++){JSONObject list=lists.getJSONObject(i);Button button=action((list.optBoolean("smart")?"ϟ ":"♫ ")+list.optString("name"),()->edit(list));button.setOnLongClickListener(v->{menu(list);return true;});addView(button);}}catch(Exception error){error(error);}}
    private void create(boolean smart){EditText name=new EditText(activity);name.setHint(smart?"Smart Playlist name":"Playlist name");new AlertDialog.Builder(activity).setTitle("New playlist").setView(name).setPositiveButton("Create",(d,w)->{try{String value=name.getText().toString().trim();if(value.isEmpty()){Toast.makeText(activity,"Enter a playlist name",Toast.LENGTH_SHORT).show();return;}JSONObject list=new JSONObject().put("id",UUID.randomUUID().toString()).put("name",value).put("smart",smart).put("songs",new JSONArray()).put("source","");PhonePlaylists.save(activity,list);draw();edit(list);}catch(Exception error){error(error);}}).setNegativeButton("Cancel",null).show();}
    private void menu(JSONObject list){new AlertDialog.Builder(activity).setTitle(list.optString("name")).setItems(new String[]{"Edit","Play / rebuild order","Delete"},(d,n)->{if(n==0)edit(list);if(n==1)play(list);if(n==2)new AlertDialog.Builder(activity).setTitle("Delete playlist?").setMessage("Songs and original files are retained.").setPositiveButton("Delete",(a,b)->{try{PhonePlaylists.remove(activity,list.getString("id"));draw();}catch(Exception error){error(error);}}).setNegativeButton("Cancel",null).show();}).show();}
    private void play(JSONObject list){Toast.makeText(activity,"Preparing playlist…",Toast.LENGTH_SHORT).show();java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();worker.execute(()->{try{List<MediaItem> songs=PhonePlaylists.tracks(activity,list);if(songs.isEmpty())throw new IllegalArgumentException("Choose a music source or add songs first");activity.runOnUiThread(()->{if(!activity.isFinishing())host.play(songs);});}catch(Exception error){activity.runOnUiThread(()->error(error));}finally{worker.shutdown();}});}
    private void edit(JSONObject original){try{
        JSONObject list=new JSONObject(original.toString());LinearLayout body=new LinearLayout(activity);body.setOrientation(VERTICAL);body.setBackgroundColor(colors.surface);body.setPadding(18,12,18,18);ScrollView scroll=new ScrollView(activity);scroll.addView(body);EditText name=new EditText(activity);name.setTextColor(colors.text);name.setHintTextColor(colors.muted);name.setText(list.optString("name"));body.addView(name);
        if(list.optBoolean("smart")){
            body.addView(label("Music source · every song is automatically included"));TextView source=label(sourceSummary(list));body.addView(source);
            body.addView(action("Choose music sources",()->sources(list,source)));
            body.addView(action("Choose individual songs",()->selectSongs(list,()->{try{JSONArray selected=list.optJSONArray("sources");if(selected==null){selected=new JSONArray();if(!list.optString("source").isEmpty())selected.put(list.optString("source"));}if(!PhoneSmartRules.contains(selected,"selection"))selected.put("selection");list.put("sources",selected).put("source",selected.optString(0));source.setText(sourceSummary(list));}catch(Exception e){error(e);}})));
            body.addView(label("Mixing style"));RadioGroup style=new RadioGroup(activity);style.setOrientation(HORIZONTAL);String[] styles={"Hype","Steady","Chill"};for(int i=0;i<styles.length;i++){RadioButton option=new RadioButton(activity);option.setId(android.view.View.generateViewId());option.setText(styles[i]);option.setTextColor(colors.text);style.addView(option);if(styles[i].equalsIgnoreCase(list.optString("style","Steady")))style.check(option.getId());}body.addView(style);
            Switch manual=new Switch(activity);manual.setText("Manual target energy");manual.setTextColor(colors.text);manual.setChecked(list.optDouble("energy",-1)>=0);body.addView(manual);SeekBar energy=new SeekBar(activity);energy.setMax(100);energy.setProgress((int)(Math.max(0,list.optDouble("energy",.5))*100));body.addView(energy);
            body.addView(label("Uses synced desktop analysis and local overrides. No analysis engine runs on your phone. Filters needing missing metadata will not match."));
            body.addView(action("Preview suggested order",()->{try{list.put("style",styles[styleIndex(style)]).put("energy",manual.isChecked()?energy.getProgress()/100.:-1);preview(list);}catch(Exception error){error(error);}}));
            body.addView(action("Genres, analysis filters & advanced options",()->new PhoneSmartEditor(activity,colors,list).show()));
            body.setTag(new Object[]{style,manual,energy});
        }else{
            body.addView(action("Choose songs",()->selectSongs(list,()->{})));body.addView(action("Edit song order",()->order(list)));
        }
        AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Edit playlist").setView(scroll).setPositiveButton("Save Playlist",null).setNeutralButton("Play",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(v->{dialog.getButton(-1).setOnClickListener(b->{try{String value=name.getText().toString().trim();if(value.isEmpty())throw new IllegalArgumentException("Enter a playlist name");list.put("name",value);if(list.optBoolean("smart")){Object[] fields=(Object[])body.getTag();list.put("style",new String[]{"Hype","Steady","Chill"}[styleIndex((RadioGroup)fields[0])]).put("energy",((Switch)fields[1]).isChecked()?((SeekBar)fields[2]).getProgress()/100.:-1);if(list.optString("source").isEmpty()&&(list.optJSONArray("sources")==null||list.optJSONArray("sources").length()==0))throw new IllegalArgumentException("Choose a music source first");}PhonePlaylists.save(activity,list);dialog.dismiss();draw();}catch(Exception error){error(error);}});dialog.getButton(-3).setOnClickListener(b->{try{if(list.optBoolean("smart")){Object[] fields=(Object[])body.getTag();list.put("style",new String[]{"Hype","Steady","Chill"}[styleIndex((RadioGroup)fields[0])]).put("energy",((Switch)fields[1]).isChecked()?((SeekBar)fields[2]).getProgress()/100.:-1);}play(list);}catch(Exception error){error(error);}});});dialog.show();
    }catch(Exception error){error(error);}}
    private void preview(JSONObject draft){try{JSONObject snapshot=new JSONObject(draft.toString());Toast.makeText(activity,"Preparing preview…",Toast.LENGTH_SHORT).show();java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();worker.execute(()->{try{List<MediaItem> ordered=PhonePlaylists.tracks(activity,snapshot);StringBuilder text=new StringBuilder();for(int i=0;i<Math.min(100,ordered.size());i++)text.append(i+1).append(". ").append(ordered.get(i).mediaMetadata.title).append('\n');activity.runOnUiThread(()->{if(!activity.isFinishing())new AlertDialog.Builder(activity).setTitle("Mix order · "+ordered.size()+" songs").setMessage(text.length()==0?"No songs match. Check sources, downloaded music and filters.":text.toString()).setPositiveButton("Done",null).show();});}catch(Exception e){activity.runOnUiThread(()->error(e));}finally{worker.shutdown();}});}catch(Exception e){error(e);}}
    private static int styleIndex(RadioGroup group){return Math.max(0,group.indexOfChild(group.findViewById(group.getCheckedRadioButtonId())));}
    private String sourceSummary(JSONObject list){JSONArray sources=list.optJSONArray("sources");if(sources==null)return sourceName(list.optString("source"));if(sources.length()==0)return "Choose folders or playlists";StringBuilder text=new StringBuilder();for(int i=0;i<sources.length();i++){if(i>0)text.append("\n");text.append(sourceName(sources.optString(i)));}return text.toString();}
    private String sourceName(String source){if(source.equals("all"))return "All phone music";if(source.equals("selection"))return "Selected individual songs";if(source.startsWith("folder:"))return source.substring(7);try{JSONArray lists=PhonePlaylists.read(activity);for(int i=0;i<lists.length();i++)if(source.equals(lists.getJSONObject(i).optString("id")))return lists.getJSONObject(i).optString("name");}catch(Exception ignored){}return "Choose a folder or playlist";}
    private void sources(JSONObject list,TextView label){try{List<String> names=new ArrayList<>(),ids=new ArrayList<>();names.add("All phone music");ids.add("all");names.add("Selected individual songs");ids.add("selection");Set<String> folders=new TreeSet<>();for(Object value:activity.getSharedPreferences("phone-folders",0).getAll().values())if(value instanceof String)folders.add((String)value);for(String folder:folders){names.add("Folder · "+folder);ids.add("folder:"+folder);}JSONArray lists=PhonePlaylists.read(activity);for(int i=0;i<lists.length();i++){JSONObject other=lists.getJSONObject(i);if(!other.optBoolean("smart")){names.add("Playlist · "+other.optString("name"));ids.add(other.getString("id"));}}JSONArray selected=list.optJSONArray("sources");if(selected!=null)for(int i=0;i<selected.length();i++)if(!ids.contains(selected.optString(i))){ids.add(selected.optString(i));names.add("Unavailable source · "+sourceName(selected.optString(i)));}boolean[] checked=new boolean[ids.size()];for(int i=0;i<ids.size();i++)checked[i]=selected==null?ids.get(i).equals(list.optString("source")):PhoneSmartRules.contains(selected,ids.get(i));new AlertDialog.Builder(activity).setTitle("Music sources · includes subfolders").setMultiChoiceItems(names.toArray(new String[0]),checked,(d,n,value)->checked[n]=value).setPositiveButton("Use sources",(d,n)->{try{JSONArray next=new JSONArray();for(int i=0;i<ids.size();i++)if(checked[i])next.put(ids.get(i));list.put("sources",next).put("source",next.length()>0?next.getString(0):"");label.setText(sourceSummary(list));}catch(Exception error){error(error);}}).setNegativeButton("Cancel",null).show();}catch(Exception error){error(error);}}
    private void selectSongs(JSONObject list,Runnable done){try{List<MediaItem> library=LibraryStore.read(activity);String[] titles=new String[library.size()];boolean[] checked=new boolean[library.size()];Set<String> selected=new HashSet<>();JSONArray old=list.optJSONArray("songs");if(old!=null)for(int i=0;i<old.length();i++)selected.add(old.getString(i));for(int i=0;i<library.size();i++){titles[i]=String.valueOf(library.get(i).mediaMetadata.title);checked[i]=selected.contains(library.get(i).mediaId);}new AlertDialog.Builder(activity).setTitle("Playlist songs").setMultiChoiceItems(titles,checked,(d,n,value)->checked[n]=value).setPositiveButton("Use songs",(d,n)->{try{JSONArray songs=new JSONArray();Set<String> added=new HashSet<>();if(old!=null)for(int i=0;i<old.length();i++)for(int j=0;j<library.size();j++)if(checked[j]&&old.getString(i).equals(library.get(j).mediaId)){songs.put(old.getString(i));added.add(old.getString(i));}for(int i=0;i<library.size();i++)if(checked[i]&&added.add(library.get(i).mediaId))songs.put(library.get(i).mediaId);list.put("songs",songs);done.run();}catch(Exception error){error(error);}}).setNegativeButton("Cancel",null).show();}catch(Exception error){error(error);}}
    private void order(JSONObject list){try{List<MediaItem> tracks=PhonePlaylists.tracks(activity,list);String[] titles=new String[tracks.size()];for(int i=0;i<tracks.size();i++)titles[i]=(i+1)+". "+tracks.get(i).mediaMetadata.title;new AlertDialog.Builder(activity).setTitle("Choose a song to move").setItems(titles,(d,n)->new AlertDialog.Builder(activity).setItems(new String[]{"Move up","Move down","Remove"},(a,op)->{try{List<MediaItem> next=new ArrayList<>(tracks);if(op==0&&n>0)Collections.swap(next,n,n-1);if(op==1&&n+1<next.size())Collections.swap(next,n,n+1);if(op==2)next.remove(n);JSONArray ids=new JSONArray();for(MediaItem song:next)ids.put(song.mediaId);list.put("songs",ids);order(list);}catch(Exception error){error(error);}}).show()).setNegativeButton("Done",null).show();}catch(Exception error){error(error);}}
    static void trackDetails(Activity activity,MediaItem item){Appearance palette=new Appearance(activity);LinearLayout form=new LinearLayout(activity);form.setOrientation(VERTICAL);form.setBackgroundColor(palette.surface);EditText bpm=new EditText(activity),key=new EditText(activity);bpm.setTextColor(palette.text);bpm.setHintTextColor(palette.muted);key.setTextColor(palette.text);key.setHintTextColor(palette.muted);bpm.setInputType(8194);bpm.setHint("BPM (blank if unknown)");double current=PhonePlaylists.bpm(activity,item);bpm.setText(current>0?String.valueOf(current):"");key.setHint("Key / Camelot (optional)");SharedPreferences prefs=activity.getSharedPreferences("phone-track-details",0);key.setText(prefs.getString(item.mediaId+":key",""));form.addView(bpm);form.addView(key);RatingBar rating=new RatingBar(activity,null,android.R.attr.ratingBarStyleSmall);rating.setIsIndicator(false);rating.setNumStars(5);rating.setStepSize(1);rating.setRating(prefs.getInt(item.mediaId+":rating",0));form.addView(rating);TextView label=new TextView(activity);label.setTextColor(palette.text);label.setText("Energy · 0–100% (local override)");form.addView(label);SeekBar energy=new SeekBar(activity);energy.setMax(100);energy.setProgress((int)(PhonePlaylists.energy(activity,item)*100));form.addView(energy);AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(String.valueOf(item.mediaMetadata.title)).setView(form).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{String value=bpm.getText().toString().trim();float tempo=value.isEmpty()?0:Float.parseFloat(value);if(!Float.isFinite(tempo)||tempo<0||tempo>400)throw new IllegalArgumentException("BPM must be between 0 and 400");prefs.edit().putFloat(item.mediaId+":bpm",tempo).putString(item.mediaId+":key",key.getText().toString().trim()).putFloat(item.mediaId+":energy",energy.getProgress()/100f).putInt(item.mediaId+":rating",(int)rating.getRating()).apply();dialog.dismiss();}catch(Exception error){Toast.makeText(activity,error.getMessage(),Toast.LENGTH_LONG).show();}}));dialog.show();}
}
